  if (/^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} (?:\S+ )?sshd$$\d+$$: Failed password for (?:invalid user )?(\w+)/) {
    $count{"$1\t$2"}++;
