#!/usr/bin/perl
use strict;
use warnings;

# Month mapping
my %m = (
  Jan => "01", Feb => "02", Mar => "03", Apr => "04", May => "05", Jun => "06",
  Jul => "07", Aug => "08", Sep => "09", Oct => "10", Nov => "11", Dec => "12"
);

# Get target date (default to yesterday)
my $target_date = shift || yesterday();

# Parse target date
my ($target_y, $target_m, $target_d) = split(/-/, $target_date);
$target_m = sprintf("%02d", $target_m);
$target_d = sprintf("%02d", $target_d);

my %counts;

sub yesterday {
  my @yesterday = localtime(time - 86400); # 86400 seconds = 1 day
  return sprintf("%04d-%02d-%02d", $yesterday[5] + 1900, $yesterday[4] + 1, $yesterday[3]);
}

sub is_old_format {
  my $line = shift;
  return 1 if $line =~ /^([A-Z][a-z]{2}) +(\d{1,2})/;
  return 0;
}

sub get_date_from_line {
  my $line = shift;
  if ($line =~ /^(\d{4}-\d{2}-\d{2})/) {
    return $1;
  } elsif (is_old_format($line)) {
    my ($mon, $day) = ($1, $2) if $line =~ /^([A-Z][a-z]{2}) +(\d{1,2})/;
    return "$target_y-" . ($m{$mon} || "00") . "-$day";
  }
  return undef;
}

sub is_failed_login {
  my $line = shift;
  return 1 if $line =~ /Failed password for/;
  return 1 if $line =~ /Authentication failure for/;
  return 0;
}

sub extract_user {
  my $line = shift;
  if ($line =~ /Failed password for (?:invalid user )?(\w+)/) {
    return $1;
  } elsif ($line =~ /Authentication failure for (\w+)/) {
    return $1;
  }
  return undef;
}

# Files to check
my @files = ('/var/log/auth.log');
push @files, '/var/log/auth.log.1' if -f '/var/log/auth.log.1';

# Process each file
for my $file (@files) {
  open(my $fh, '<', $file) or die "Can't open $file: $!";
  while (my $line = <$fh>) {
    my $date = get_date_from_line($line);
    next unless $date && $date eq $target_date;
    next unless is_failed_login($line);
    my $user = extract_user($line);
    next unless $user;
    $counts{$user}++;
  }
  close $fh;
}

# Alert if any user has > 50 failed logins
my @alerts = grep { $counts{$_} > 50 } keys %counts;
if (@alerts) {
