#!/usr/bin/perl
use strict;
use warnings;

# Month mapping
my %m = (
  Jan => "01", Feb => "02", Mar => "03", Apr => "04", May => "05", Jun => "06",
  Jul => "07", Aug => "08", Sep => "09", Oct => "10", Nov => "11", Dec => "12"
);

# Get target date (default to yesterday)
my $target_date = shift || yesterday();

my ($target_y, $target_m, $target_d) = split(/-/, $target_date);
$target_m = sprintf("%02d", $target_m);
$target_d = sprintf("%02d", $target_d);

my %counts;

sub yesterday {
  my @yesterday = localtime(time - 86400); # 86400 seconds = 1 day
  return sprintf("%04d-%02d-%02d", $yesterday[5] + 1900, $yesterday[4] + 1, $yesterday[3]);
}

sub is_failed_login {
  my $line = shift;
  return 1 if $line =~ /^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} (?:\S+ )?sshd$$\d+$$: Failed password for/;
  return 1 if $line =~ /^([A-Z][a-z]{2}) +(\d{1,2}) \d{2}:\d{2}:\d{2} \S+ sshd$$\d+$$: Authentication failure for/;
  return 0;
}

sub extract_date_and_user {
  my $line = shift;

  if ($line =~ /^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} (?:\S+ )?sshd$$\d+$$: Failed password for (?:invalid user )?(\w+)/) {
    return ($1, $2);
  } elsif ($line =~ /^([A-Z][a-z]{2}) +(\d{1,2}) \d{2}:\d{2}:\d{2} \S+ sshd$$\d+$$: Authentication failure for (\w+)/) {
    my $mon = $1;
    my $day = $2;
    my $user = $3;
    my $month = $m{$mon} || "00";
    my $day_padded = sprintf("%02d", $day);
    my $date = "$target_y-$month-$day_padded";
    return ($date, $user);
  }
  return (undef, undef);
}

# Files to check
my @files = ('/var/log/auth.log');
push @files, '/var/log/auth.log.1' if -f '/var/log/auth.log.1';

# Process each file
for my $file (@files) {
  open(my $fh, '<', $file) or die "Can't open $file: $!";
  while (my $line = <$fh>) {
    next unless is_failed_login($line);
    my ($date, $user) = extract_date_and_user($line);
    next unless $date && $user && $date eq $target_date;
    $counts{$user}++;
  }
  close $fh;
}

# Output to file
my $output_file = "/var/log/loginstats/$target_date.txt";
unless (-d "/var/log/loginstats") {
  system("mkdir -p /var/log/loginstats") == 0 or die "Failed to create /var/log/loginstats: $!";
}
open(my $out, '>', $output_file) or die "Can't open $output_file: $!";
for my $user (sort keys %counts) {
  print $out "$counts{$user}\t$target_date\t$user\n";
}
close $out;

# Alert only if any user has > 50 failed logins
my @alerts = grep { $counts{$_} > 50 } keys %counts;
if (@alerts) {
  print "ALERT: The following users had more than 50 failed logins on $target_date:\n";
  for my $user (@alerts) {
    print "  $user: $counts{$user} attempts\n";
  }
}
